import {
  Children,
  cloneElement,
  type HTMLAttributes,
  isValidElement,
  type LiHTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react";
import { cx } from "../utils/cx";
import { CheckIcon } from "../icons/interface";

export type StepperProps = HTMLAttributes<HTMLOListElement> & {
  /** Zero-based index of the current step. Earlier steps are complete, later ones upcoming. */
  current: number;
  orientation?: "horizontal" | "vertical";
};

/** A sequence of steps. Status is derived from `current`, so children are just `Step`s. Server-compatible. */
export function Stepper({ current, orientation = "horizontal", className, children, ...rest }: StepperProps) {
  const steps = Children.toArray(children).filter(isValidElement) as ReactElement<
    StepProps & { "data-index"?: number }
  >[];
  return (
    <ol {...rest} className={cx("hm-stepper", className)} data-orientation={orientation}>
      {steps.map((step, i) =>
        cloneElement(step, {
          "data-index": i + 1,
          "data-status": i < current ? "complete" : i === current ? "current" : "upcoming",
          "aria-current": i === current ? "step" : undefined,
        } as object),
      )}
    </ol>
  );
}

export type StepProps = LiHTMLAttributes<HTMLLIElement> & {
  title: ReactNode;
  description?: ReactNode;
};

export function Step({ title, description, className, ...rest }: StepProps) {
  const index = (rest as { "data-index"?: number })["data-index"];
  const status = (rest as { "data-status"?: string })["data-status"];
  return (
    <li {...rest} className={cx("hm-step", className)}>
      <span className="hm-step-marker" aria-hidden="true">
        {status === "complete" ? <CheckIcon size={12} strokeWidth={2} /> : index}
      </span>
      <span className="hm-step-text">
        <span className="hm-step-title">{title}</span>
        {description ? <span className="hm-step-description">{description}</span> : null}
        {status === "complete" ? <span className="hm-sr-only"> (completed)</span> : null}
      </span>
    </li>
  );
}
